new = """inline Route make_route(const std::string& s, int length, int hop) {
    if (length < 0 || length > 128) throw std::runtime_error("prefix length");
    if (s.size() != 32) throw std::runtime_error("key width");
    Key raw = key(s);
    Route r;
    r.length = length;
    r.hop = hop;
    // Host bits are masked off, so the route starts at its network address.
    r.start = (length == 0) ? Key(0) : ((raw >> (128 - length)) << (128 - length));
    return r;
}"""
assert old in s
s = s.replace(old, new)
